set-variable.value:
@{
			string path = context.Request.MatchedParameters.GetValueOrDefault("path", "");
			string marker = "deployments/";
			int markerIndex = path.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
			if (markerIndex < 0) { return true; }
			int start = markerIndex + marker.Length;
			int end = path.IndexOf('/', start);
			string pathDeployment = end < 0 ? path.Substring(start) : path.Substring(start, end - start);
			string detectedModel = context.Variables.GetValueOrDefault<string>("model", "");
			return !string.IsNullOrWhiteSpace(pathDeployment) &&
				string.Equals(pathDeployment, detectedModel, StringComparison.OrdinalIgnoreCase);
		}

@{
			JObject loaded = context.Variables.GetValueOrDefault<JObject>("throttleState", null);
			JObject map = (loaded != null && loaded["backends"] != null && loaded["backends"].Type == JTokenType.Object) ? (JObject)loaded["backends"] : new JObject();
			return new JObject(
				new JProperty("dirty", false),
				new JProperty("backends", map)
			);
		}

@{
			JArray backends = (JArray)context.Variables["listBackends"];
			JObject state = (JObject)((JObject)context.Variables["throttleState"])["backends"];
			DateTime now = DateTime.UtcNow;
			foreach (JObject b in backends) {
				DateTime wakeAt = state.Value<DateTime?>(b.Value<string>("affinity")) ?? DateTime.MinValue;
				bool isThrottling = wakeAt > now;
				b["isThrottling"] = isThrottling;
				b["retryAfter"] = isThrottling ? wakeAt : DateTime.MinValue;
			}
			return backends;
		}

@{
			const int defaultPriority = 3;
			string priorityHeaderName = (string)context.Variables["priorityHeaderName"];
			return context.Request.Headers.TryGetValue(priorityHeaderName, out var priorityValues) &&
				int.TryParse(priorityValues.FirstOrDefault(), out int parsedPriority)
				? parsedPriority
				: defaultPriority;
		}

@{
			string affinityHeaderName = (string)context.Variables["AffinityHeaderName"];
			string affinityHeader = context.Request.Headers.GetValueOrDefault(affinityHeaderName, "");

			// Find the backend with the matching affinity
			if (!string.IsNullOrEmpty(affinityHeader)) {
				JArray backends = (JArray)context.Variables["listBackends"];
				for (int i = 0; i < backends.Count; i++) {
					JObject backend = (JObject)backends[i];
					if (string.Equals(backend["affinity"]?.ToString(), affinityHeader, StringComparison.OrdinalIgnoreCase)) {
						return i;  // Return the index of the matching backend
					}
				}
			}

			// Return -1 if no affinity header or no match found
			return -1;
		}

@{
			JArray list =  new JArray();
			JArray backends = (JArray)context.Variables["listBackends"];
			int requestPriority = (int)context.Variables["RequestPriority"];
			for (int i = 0; i < backends.Count; i++) {
				JObject backend = (JObject)backends[i];
				if (backend["acceptablePriorities"]?.Values<int>().Contains(requestPriority) == true) {
					list.Add(i);
				}
			}
			return list;
		}

@{
			string policyCycleCounterHeaderName = (string)context.Variables["PolicyCycleCounterHeaderName"];
			return context.Request.Headers.TryGetValue(policyCycleCounterHeaderName, out var priorityValues) &&
				int.TryParse(priorityValues.FirstOrDefault(), out int parsedCounter)   ? parsedCounter : 0;   // return 0 if not set
		}

@{
			// Initialize or reuse
			JArray arr = context.Variables.GetValueOrDefault<JArray>("lastPolicyError", new JArray());
			arr.Clear();
			arr.Add(new JObject {
				{ "code", "init" },
				{ "message", "noError" }
			});
			return arr;
		}

@{
			// Request Start
			JArray arr = context.Variables.GetValueOrDefault<JArray>("activityLog", new JArray());
			arr.Clear();
			arr.Add(new JObject {
				{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3")},
				{ "message", "Begin" }
			});
			return arr;
		}

@{
			var headers = context.Request.Headers;
			if (!string.Equals(headers.GetValueOrDefault("S7PDEBUG", ""), "true", StringComparison.OrdinalIgnoreCase)) {
				return "";
			}

			string priorityHeaderName = (string)context.Variables["priorityHeaderName"];
			JObject dbgObj = new JObject {
				{ "Proxy-Queue-Duration", headers.GetValueOrDefault("x-Request-Queue-Duration", "N/A") },
				{ "Proxy-Process-Duration", headers.GetValueOrDefault("x-Request-Process-Duration", "N/A") },
				{ "S7PID", headers.GetValueOrDefault("x-S7P-ID", "N/A") },
				{ priorityHeaderName, headers.GetValueOrDefault(priorityHeaderName, "N/A") },
				{ "Priority", context.Variables.GetValueOrDefault<int>("RequestPriority", 3) }
			};

			return string.Join(" | ", dbgObj.Properties().Select(p => p.Name + ": " + p.Value));
		}
